{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.chart2_flipkart_with_ro AS WITH asof_window AS ( SELECT MAX(TO_DATE(ORDER_DATE_KEY::VARCHAR, \'YYYYMMDD\')) AS window_end FROM snitch_db.maplemonk.v_s3_mtd_sales ), f_fsn_style_raw AS ( SELECT FSN, STYLE_CODE, 1 AS pri, NULL AS ord FROM snitch_db.maplemonk.v_s3_mtd_inventory WHERE NULLIF(FSN, \'\') IS NOT NULL AND NULLIF(STYLE_CODE, \'\') IS NOT NULL UNION ALL SELECT FSN, STYLE_CODE, 2 AS pri, GRN_CREATED_DATE_KEY AS ord FROM snitch_db.maplemonk.s3_fk_grn_ytd WHERE NULLIF(FSN, \'\') IS NOT NULL AND NULLIF(STYLE_CODE, \'\') IS NOT NULL ), f_fsn_style AS ( SELECT FSN, REGEXP_REPLACE(STYLE_CODE, \'-(XS|S|M|L|XL|XXL|XXXL)$\', \'\', 1, 0, \'i\') AS STYLE_CODE FROM f_fsn_style_raw QUALIFY ROW_NUMBER() OVER (PARTITION BY FSN ORDER BY pri, ord DESC NULLS LAST) = 1 ), f_style_grn AS ( SELECT m.STYLE_CODE, SUM(CASE WHEN TO_DATE(g.GRN_CREATED_DATE_KEY::VARCHAR, \'YYYYMMDD\') >= TO_DATE(\'2026-04-01\') THEN g.INB_QTY ELSE 0 END) AS qty_grned, SUM(CASE WHEN TO_DATE(g.GRN_CREATED_DATE_KEY::VARCHAR, \'YYYYMMDD\') >= TO_DATE(\'2026-04-01\') THEN g.QC_PASS_QUANTITY ELSE 0 END) AS qty_grned_qc_pass, SUM(CASE WHEN TO_DATE(g.GRN_CREATED_DATE_KEY::VARCHAR, \'YYYYMMDD\') < TO_DATE(\'2026-04-01\') THEN g.INB_QTY ELSE 0 END) AS pre_fy_grn_units, MIN(CASE WHEN TO_DATE(g.GRN_CREATED_DATE_KEY::VARCHAR, \'YYYYMMDD\') >= TO_DATE(\'2026-04-01\') THEN TO_DATE(g.GRN_CREATED_DATE_KEY::VARCHAR, \'YYYYMMDD\') END) AS style_grn_date FROM snitch_db.maplemonk.s3_fk_grn_ytd g JOIN f_fsn_style m ON m.FSN = g.FSN GROUP BY m.STYLE_CODE HAVING SUM(CASE WHEN TO_DATE(g.GRN_CREATED_DATE_KEY::VARCHAR, \'YYYYMMDD\') >= TO_DATE(\'2026-04-01\') THEN g.INB_QTY ELSE 0 END) > 0 ), f_style_ro AS ( SELECT REGEXP_REPLACE(SKU, \'-(XS|S|M|L|XL|XXL|XXXL)$\', \'\', 1, 0, \'i\') AS STYLE_CODE, SUM(QTY) AS ro_qty_raised FROM snitch_db.maplemonk.s3_flipkart_ro WHERE FY2627_IN_SCOPE = TRUE GROUP BY REGEXP_REPLACE(SKU, \'-(XS|S|M|L|XL|XXL|XXXL)$\', \'\', 1, 0, \'i\') ), f_style_soh AS ( SELECT m.STYLE_CODE, SUM(i.QOH) AS current_soh FROM snitch_db.maplemonk.v_s3_mtd_inventory i JOIN f_fsn_style m ON m.FSN = i.FSN GROUP BY m.STYLE_CODE ), f_style_in_catalog AS ( SELECT DISTINCT m.STYLE_CODE FROM snitch_db.maplemonk.v_s3_mtd_inventory i JOIN f_fsn_style m ON m.FSN = i.FSN ), f_style_sold_dates AS ( SELECT m.STYLE_CODE, s.UNITS, TO_DATE(s.ORDER_DATE_KEY::VARCHAR, \'YYYYMMDD\') AS order_date FROM snitch_db.maplemonk.v_s3_mtd_sales s JOIN f_fsn_style m ON m.FSN = s.FSN WHERE TO_DATE(s.ORDER_DATE_KEY::VARCHAR, \'YYYYMMDD\') >= TO_DATE(\'2026-04-01\') ), f_style_sold_after_grn AS ( SELECT d.STYLE_CODE, SUM(d.UNITS) AS qty_sold_after_grn FROM f_style_sold_dates d JOIN f_style_grn g ON g.STYLE_CODE = d.STYLE_CODE WHERE d.order_date >= g.style_grn_date GROUP BY d.STYLE_CODE ), f_style_ros AS ( SELECT d.STYLE_CODE, SUM(CASE WHEN d.order_date >= DATEADD(day, -6, a.window_end) THEN d.UNITS ELSE 0 END) / 7.0 AS ros_7, SUM(CASE WHEN d.order_date >= DATEADD(day, -13, a.window_end) THEN d.UNITS ELSE 0 END) / 14.0 AS ros_14, SUM(CASE WHEN d.order_date >= DATEADD(day, -27, a.window_end) THEN d.UNITS ELSE 0 END) / 28.0 AS ros_28 FROM f_style_sold_dates d CROSS JOIN asof_window a GROUP BY d.STYLE_CODE ), f_calc AS ( SELECT g.STYLE_CODE AS sku, g.qty_grned, g.pre_fy_grn_units, CASE WHEN c.STYLE_CODE IS NULL THEN NULL ELSE COALESCE(a.qty_sold_after_grn, 0) + COALESCE(ro.ro_qty_raised, 0) END AS qty_sold_after_grn, s.current_soh, CASE WHEN c.STYLE_CODE IS NULL THEN NULL ELSE g.qty_grned - COALESCE(a.qty_sold_after_grn, 0) - COALESCE(ro.ro_qty_raised, 0) END AS expected_inventory, COALESCE(r.ros_7, 0) AS ros_7, COALESCE(r.ros_14, 0) AS ros_14, COALESCE(r.ros_28, 0) AS ros_28, c.STYLE_CODE AS in_catalog_flag FROM f_style_grn g LEFT JOIN f_style_in_catalog c ON c.STYLE_CODE = g.STYLE_CODE LEFT JOIN f_style_sold_after_grn a ON a.STYLE_CODE = g.STYLE_CODE LEFT JOIN f_style_soh s ON s.STYLE_CODE = g.STYLE_CODE LEFT JOIN f_style_ros r ON r.STYLE_CODE = g.STYLE_CODE LEFT JOIN f_style_ro ro ON ro.STYLE_CODE = g.STYLE_CODE ) SELECT \'FLIPKART_SOR\' AS channel, sku, qty_grned, qty_sold_after_grn, current_soh, expected_inventory, CASE WHEN in_catalog_flag IS NULL OR current_soh IS NULL OR expected_inventory IS NULL THEN NULL WHEN expected_inventory <= 0 THEN NULL WHEN expected_inventory < 10 OR expected_inventory < qty_grned * 0.05 THEN NULL ELSE ROUND((current_soh - expected_inventory) / expected_inventory * 100, 2) END AS discrepancy_pct, CASE WHEN in_catalog_flag IS NULL OR current_soh IS NULL OR expected_inventory IS NULL THEN NULL WHEN expected_inventory < 0 THEN NULL ELSE current_soh - expected_inventory END AS variance_units, CASE WHEN in_catalog_flag IS NULL OR expected_inventory IS NULL THEN NULL WHEN expected_inventory < 0 THEN -expected_inventory ELSE 0 END AS implied_pre_window_stock, CASE WHEN in_catalog_flag IS NULL OR current_soh IS NULL THEN \'NO_INVENTORY_RECORD\' WHEN expected_inventory < 0 THEN \'PRE_WINDOW_STOCK\' WHEN expected_inventory = 0 THEN \'FULLY_DEPLETED\' WHEN expected_inventory < 10 OR expected_inventory < qty_grned * 0.05 THEN \'LOW_BASE\' ELSE \'OK\' END AS row_status, CASE WHEN in_catalog_flag IS NULL THEN NULL ELSE ros_7 END AS ros_7, CASE WHEN in_catalog_flag IS NULL THEN NULL ELSE ros_14 END AS ros_14, CASE WHEN in_catalog_flag IS NULL THEN NULL ELSE ros_28 END AS ros_28, \'SKU_LEVEL_WITH_RO\' AS grn_grain, pre_fy_grn_units FROM f_calc ORDER BY sku;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from SNITCH_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            